import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.DXa1R37q.js";const k=JSON.parse('{"title":"Troubleshoot Neottia","description":"","frontmatter":{},"headers":[],"relativePath":"operate/troubleshooting.md","filePath":"operate/troubleshooting.md","lastUpdated":1793054524000}'),o={name:"operate/troubleshooting.md"};function n(r,e,l,p,h,d){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="troubleshoot-neottia" tabindex="-1">Troubleshoot Neottia <a class="header-anchor" href="#troubleshoot-neottia" aria-label="Permalink to &quot;Troubleshoot Neottia&quot;">​</a></h1><p>Start with these two commands from the project root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>The human report gives remediation. The JSON report gives stable diagnostic codes for automation and issue reports.</p><h2 id="the-cli-does-not-start" tabindex="-1">The CLI does not start <a class="header-anchor" href="#the-cli-does-not-start" aria-label="Permalink to &quot;The CLI does not start&quot;">​</a></h2><p><strong>Check:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neottia</span></span></code></pre></div><p><strong>Fix:</strong> Use Node.js 22.20 or newer and pnpm 10 or newer. Reinstall <code>@neottia/cli</code> from a trusted registry. Claude Code runtime modules also need <code>npx</code> on <code>PATH</code>.</p><h2 id="apply-reports-a-conflict" tabindex="-1"><code>apply</code> reports a conflict <a class="header-anchor" href="#apply-reports-a-conflict" aria-label="Permalink to &quot;\`apply\` reports a conflict&quot;">​</a></h2><p>Neottia found an existing unowned path or a receipt-owned path that changed after installation. It skips the path and exits non-zero instead of overwriting it.</p><p><strong>Fix:</strong></p><ol><li>Read every <code>WARN</code> path and reason.</li><li>Preserve or move operator-owned content.</li><li>If replacement is intentional, generate a reviewable plan and approve the exact conflict ID.</li><li>Apply the unchanged saved plan.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sdlc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.plan.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --approve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conflict.0123456789abcdef</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.plan.json</span></span></code></pre></div><p>There is no wildcard approval and no force option.</p><h2 id="the-host-does-not-show-plan" tabindex="-1">The host does not show <code>/plan</code> <a class="header-anchor" href="#the-host-does-not-show-plan" aria-label="Permalink to &quot;The host does not show \`/plan\`&quot;">​</a></h2><p><strong>Check:</strong> Run <code>neottia doctor</code>, then inspect the harness receipt under <code>.neottia/install/</code>.</p><p><strong>Fix by host:</strong></p><ul><li><strong>Pi:</strong> restart Pi in the project and inspect project package settings.</li><li><strong>OpenCode:</strong> restart OpenCode and inspect its project plugin configuration.</li><li><strong>Claude Code:</strong> inspect every server in <code>.mcp.json</code>, restart Claude Code, open <code>/mcp</code>, and approve only the expected project servers. Neottia preserves unrelated project entries.</li></ul><p>Confirm that the host process uses the repository root as its working directory.</p><h2 id="a-tool-reports-that-its-capability-is-disabled" tabindex="-1">A tool reports that its capability is disabled <a class="header-anchor" href="#a-tool-reports-that-its-capability-is-disabled" aria-label="Permalink to &quot;A tool reports that its capability is disabled&quot;">​</a></h2><p><strong>Check:</strong> Inspect <code>.neottia/config.yml</code> for the matching <code>modules.*.enabled</code> value and capability provider.</p><p><strong>Fix:</strong> Enable the module and select the matching provider, then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Memory provider and backend selections must agree. Searchable lifecycle use requires <code>capabilities.searchable.provider: web</code> and an enabled Searchable module.</p><h2 id="doctor-rejects-the-platform-or-filesystem" tabindex="-1">Doctor rejects the platform or filesystem <a class="header-anchor" href="#doctor-rejects-the-platform-or-filesystem" aria-label="Permalink to &quot;Doctor rejects the platform or filesystem&quot;">​</a></h2><p><strong>Check:</strong> Compare the report with the <a href="/projects/neottia/get-started/requirements#certified-repository-store-tuples">certified tuples</a>.</p><p><strong>Fix:</strong> Move the project to a supported local filesystem and runtime. Do not treat a network mount, removable device, unlisted Unix system, Windows arm64, FreeBSD arm64, or FreeBSD Bun as supported.</p><p>A matching filesystem name is not sufficient. The behavior probes must also pass.</p><h2 id="native-installation-or-integrity-fails" tabindex="-1">Native installation or integrity fails <a class="header-anchor" href="#native-installation-or-integrity-fails" aria-label="Permalink to &quot;Native installation or integrity fails&quot;">​</a></h2><ul><li>An <strong>availability</strong> failure may source-build when Python, Make, a C++17 compiler, and platform headers are available.</li><li>An <strong>integrity</strong> failure stops installation or loading. Reinstall from a trusted package source and investigate altered or conflicting assets.</li></ul><p>Do not disable digest, signature, attestation, source-commit, tuple, or workflow-identity checks.</p><h2 id="a-cache-is-stale-or-corrupt" tabindex="-1">A cache is stale or corrupt <a class="header-anchor" href="#a-cache-is-stale-or-corrupt" aria-label="Permalink to &quot;A cache is stale or corrupt&quot;">​</a></h2><p>Canonical files are authoritative. Validate them before rebuilding a disposable SQLite projection.</p><p>Depending on the capability, remove or rebuild only:</p><ul><li><code>.neottia/memory/index.db*</code>;</li><li><code>.neottia/cache/</code> database files.</li></ul><p>Do not delete canonical Memory, Issues, Design Docs, or Searchable records. See <a href="/projects/neottia/guides/upgrades-and-recovery">upgrades and recovery</a>.</p><h2 id="a-lease-blocks-work" tabindex="-1">A lease blocks work <a class="header-anchor" href="#a-lease-blocks-work" aria-label="Permalink to &quot;A lease blocks work&quot;">​</a></h2><p>A live lease means another bounded mutation owns the authority path.</p><p><strong>Fix:</strong> Wait for the owner to finish or inspect the reported owner evidence. Do not delete a live lease. If a process crashed, let Repository Store authenticate and recover the stale state.</p><h2 id="a-revision-is-stale" tabindex="-1">A revision is stale <a class="header-anchor" href="#a-revision-is-stale" aria-label="Permalink to &quot;A revision is stale&quot;">​</a></h2><p>Another writer changed the record after you read it.</p><p><strong>Fix:</strong> Fetch the current record, compare the competing change, and retry with the new revision. Do not bypass the expected revision.</p><h2 id="an-installation-stopped-during-apply" tabindex="-1">An installation stopped during apply <a class="header-anchor" href="#an-installation-stopped-during-apply" aria-label="Permalink to &quot;An installation stopped during apply&quot;">​</a></h2><p>Generate recovery from the affected receipt:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">neottia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --receipt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .neottia/install/sdlc-pi.receipt.json</span></span></code></pre></div><p>An active journal rolls back. A committed journal is cleaned up. Recovery stops when a path matches neither the recorded before-state nor intended after-state; preserve the journal and inspect the conflict.</p><h2 id="searchable-cannot-reach-the-web" tabindex="-1">Searchable cannot reach the web <a class="header-anchor" href="#searchable-cannot-reach-the-web" aria-label="Permalink to &quot;Searchable cannot reach the web&quot;">​</a></h2><p>Check the selected provider, credential environment names, target URL policy, network access, and configured timeouts. Keep credentials in the environment, not in <code>.neottia/config.yml</code>. <code>web_stash</code> and local <code>web_grep</code> do not require a live search-provider request after content is supplied.</p><h2 id="ask-for-help" tabindex="-1">Ask for help <a class="header-anchor" href="#ask-for-help" aria-label="Permalink to &quot;Ask for help&quot;">​</a></h2><p>Include:</p><ul><li><code>neottia doctor --json</code> output with secrets removed;</li><li>operating system, architecture, runtime version, and filesystem type;</li><li>the exact command and stable error code;</li><li>whether the failure is repeatable in a new temporary repository;</li><li>relevant receipt or journal metadata, without credentials or private content.</li></ul><p>Report reproducible defects in the <a href="https://github.com/dragoscirjan/neottia/issues" target="_blank" rel="noreferrer">Neottia issue tracker</a>.</p>`,52)])])}const u=t(o,[["render",n]]);export{k as __pageData,u as default};
